1	// argparse actions — mirrors CPython 3.12 `argparse.Action`, `_StoreAction`
2	// and `_HelpAction`. This layer only *stores* an argument's configuration and
3	// applies values to the namespace; all layout/wrapping lives in formatter.mjs.
4	
5	import { PyValueError } from '../py/errors.mjs';
6	
7	// CPython: argparse.SUPPRESS. A sentinel default meaning "do not put this dest
8	// into the namespace at all" (see _parse_known_args' default-seeding loop).
9	export const SUPPRESS = '==SUPPRESS==';
10	
11	// CPython: argparse.OPTIONAL ('?'), only needed for _StoreAction's const check.
12	const OPTIONAL = '?';
13	
14	/**
15	 * Normalise constructor arguments.
16	 *
17	 * CPython builds actions with keyword arguments whose names are snake_case
18	 * (`option_strings`, `const`, `default`, ...). Callers here may use either the
19	 * camelCase field names or the Python keyword names, and may also pass the
20	 * `(optionStrings, dest, options)` positional prefix that CPython's signature
21	 * begins with. All shapes collapse to one options object.
22	 */
23	function normalizeOptions(args) {
24	  const [first, second, third] = args;
25	  if (typeof first === 'string' || Array.isArray(first)) {
26	    const rest = third ?? {};
27	    return { ...rest, optionStrings: first, dest: second ?? rest.dest };
28	  }
29	  return first ?? {};
30	}
31	
32	export class Action {
33	  constructor(...args) {
34	    const opts = normalizeOptions(args);
35	    const optionStrings = opts.optionStrings ?? opts.option_strings ?? [];
36	
37	    // '--a' alone is accepted as shorthand for ['--a'].
38	    this.optionStrings = typeof optionStrings === 'string' ? [optionStrings] : [...optionStrings];
39	    this.dest = opts.dest ?? null;
40	    this.nargs = opts.nargs ?? null; // Python None => "exactly one value"
41	    this.constValue = opts.constValue ?? opts.const ?? null;
42	    this.defaultValue = opts.defaultValue ?? opts.default ?? null;
43	    this.type = opts.type ?? null;
44	    this.choices = opts.choices ?? null;
45	    this.required = opts.required ?? false;
46	    this.help = opts.help ?? null;
47	    this.metavar = opts.metavar ?? null;
48	  }
49	
50	  // CPython: Action.__call__ raises NotImplementedError('.__call__() not defined').
51	  call(parser, namespace, values, optionString) {
52	    throw new Error('.call() not defined');
53	  }
54	}
55	
56	export class StoreAction extends Action {
57	  constructor(...args) {
58	    super(...args);
59	    // CPython _StoreAction.__init__ rejects these two configurations outright.
60	    if (this.nargs === 0) {
61	      throw new PyValueError(
62	        'nargs for store actions must be != 0; if you have nothing to store, '
63	        + 'actions such as store true or store const may be more appropriate',
64	      );
65	    }
66	    if (this.constValue !== null && this.nargs !== OPTIONAL) {
67	      throw new PyValueError(`nargs must be '${OPTIONAL}' to supply const`);
68	    }
69	  }
70	
71	  // CPython: setattr(namespace, self.dest, values)
72	  call(parser, namespace, values, optionString) {
73	    namespace[this.dest] = values;
74	  }
75	}
76	
77	export class HelpAction extends Action {
78	  constructor(...args) {
79	    super(...args);
80	    // CPython _HelpAction hard-codes nargs=0 and default=SUPPRESS, and the
81	    // parser registers it with this exact help string.
82	    this.nargs = 0;
83	    this.constValue = null;
84	    this.defaultValue = SUPPRESS; // so `help` never appears in the namespace
85	    this.dest = this.dest ?? 'help';
86	    this.help = this.help ?? 'show this help message and exit';
87	  }
88	
89	  // CPython: parser.print_help(); parser.exit()  -> help on stdout, status 0.
90	  call(parser, namespace, values, optionString) {
91	    parser.printHelp();
92	    parser.exitWith(0);
93	  }
94	}
