1	// argparse exception types — mirrors CPython 3.12 `argparse._get_action_name`,
2	// `argparse.ArgumentError` and `argparse.ArgumentTypeError`.
3	
4	import { SUPPRESS } from './actions.mjs';
5	
6	/**
7	 * CPython `_get_action_name(argument)`: the label used in
8	 * `argument NAME: <message>` errors.
9	 *   optionals  -> all option strings joined with '/'  ('-h/--help')
10	 *   otherwise  -> metavar, else dest, else null
11	 * SUPPRESS placeholders count as "unset", exactly as in CPython.
12	 */
13	export function getActionName(action) {
14	  if (action == null) {
15	    return null;
16	  }
17	  if (action.optionStrings != null && action.optionStrings.length > 0) {
18	    return action.optionStrings.join('/');
19	  }
20	  if (action.metavar != null && action.metavar !== SUPPRESS) {
21	    return action.metavar;
22	  }
23	  if (action.dest != null && action.dest !== SUPPRESS) {
24	    return action.dest;
25	  }
26	  return null;
27	}
28	
29	/**
30	 * CPython `ArgumentError`. Its __str__ prefixes the message with the action
31	 * name when there is one, e.g. "argument --a: invalid int value: 'abc'".
32	 * Here that rendering is baked into `.message` since JS errors have no __str__.
33	 */
34	export class ArgumentError extends Error {
35	  constructor(action, message) {
36	    const argumentName = getActionName(action);
37	    super(argumentName == null ? message : `argument ${argumentName}: ${message}`);
38	    this.name = 'ArgumentError';
39	    this.argumentName = argumentName;
40	  }
41	}
42	
43	/** CPython `ArgumentTypeError`: raised by a `type=` callable to reject a value. */
44	export class ArgumentTypeError extends Error {
45	  constructor(message) {
46	    super(message);
47	    this.name = 'ArgumentTypeError';
48	  }
49	}
