1	// Runtime/IO layer: the slice of CPython's `sys` / `os` / `shutil` runtime that this
2	// program can observe -- argv recovery (UTF-8 + surrogateescape), byte-exact stdout /
3	// stderr writers, SystemExit, and shutil.get_terminal_size().columns.
4	//
5	// node:fs is the only bare specifier in this file: /proc/self/cmdline has to be read to
6	// recover the raw argv bytes, and fs.writeSync gives us unbuffered, byte-exact output.
7	
8	import { readFileSync, writeSync } from 'node:fs';
9	import { decodeSurrogateescape, encodeSurrogateescape } from './surrogateescape.mjs';
10	import { pyIntFromString } from './int.mjs';
11	
12	/** Fallback prog name when process.argv[1] is unavailable (mirrors the real script name). */
13	const FALLBACK_PROG = 'test3.mjs';
14	
15	/* ------------------------------------------------------------------ argv --- */
16	
17	let cachedArgv = null;
18	
19	/**
20	 * Split /proc/self/cmdline into its entries.
21	 *
22	 * The kernel writes each argument NUL-*terminated* (including the last one), so NUL is
23	 * treated as a terminator rather than a separator. That way a genuinely empty final
24	 * argument (`prog ''` -> "prog\0\0") survives, while no phantom trailing entry appears.
25	 */
26	function splitCmdline(bytes) {
27	  const parts = [];
28	  let start = 0;
29	  for (let i = 0; i < bytes.length; i += 1) {
30	    if (bytes[i] === 0) {
31	      parts.push(bytes.subarray(start, i));
32	      start = i + 1;
33	    }
34	  }
35	  // Defensive: a cmdline that is not NUL-terminated still yields its last entry.
36	  if (start < bytes.length) parts.push(bytes.subarray(start));
37	  return parts;
38	}
39	
40	/**
41	 * Recover the raw argv bytes for the user arguments and decode them the way CPython
42	 * decodes argv on Linux: UTF-8 with errors='surrogateescape', so an undecodable byte B
43	 * becomes U+DC00+B (spec 3.3). Node's own process.argv has already lost those bytes to
44	 * U+FFFD, hence the /proc round trip.
45	 *
46	 * Alignment: /proc/self/cmdline is [node, ...nodeFlags, script, ...userArgs] while
47	 * process.argv is [execPath, script, ...userArgs]; taking the LAST
48	 * (process.argv.length - 2) entries is therefore robust to node flags and to however the
49	 * interpreter path was spelled.
50	 */
51	function recoverArgv() {
52	  const lossy = process.argv.slice(2);
53	  const wanted = lossy.length;
54	  if (wanted === 0) return [];
55	
56	  const parts = splitCmdline(readFileSync('/proc/self/cmdline'));
57	  if (parts.length < wanted) return lossy;
58	  const candidate = parts.slice(parts.length - wanted);
59	
60	  // Validate the alignment: re-decoding each candidate entry the lossy way Node decoded
61	  // argv (invalid sequences -> U+FFFD) must reproduce process.argv exactly.
62	  for (let i = 0; i < wanted; i += 1) {
63	    if (candidate[i].toString('utf8') !== lossy[i]) return lossy;
64	  }
65	
66	  return candidate.map(decodeSurrogateescape);
67	}
68	
69	/** sys.argv[1:] -- the user arguments, surrogateescape-decoded. Never throws. */
70	export function getArgv() {
71	  if (cachedArgv === null) {
72	    try {
73	      cachedArgv = recoverArgv();
74	    } catch {
75	      // /proc unreadable (non-Linux, hardened container, ...): Node's lossy argv is the
76	      // best available approximation.
77	      cachedArgv = process.argv.slice(2);
78	    }
79	  }
80	  // Hand out a copy: callers treat this like `sys.argv[1:]`, a fresh list every time.
81	  return cachedArgv.slice();
82	}
83	
84	/* ------------------------------------------------------------- prog name --- */
85	
86	/**
87	 * os.path.basename(sys.argv[0]) as argparse computes `prog`.
88	 * Implemented inline (no node:path) so this module's only bare import stays node:fs.
89	 * Both '/' and '\\' are accepted as separators, and trailing separators are dropped so a
90	 * path like '/a/b/' still yields a usable name.
91	 */
92	export function getProgName() {
93	  const raw = process.argv[1];
94	  if (typeof raw !== 'string' || raw === '') return FALLBACK_PROG;
95	
96	  let end = raw.length;
97	  while (end > 1 && (raw[end - 1] === '/' || raw[end - 1] === '\\')) end -= 1;
98	  let start = end;
99	  while (start > 0 && raw[start - 1] !== '/' && raw[start - 1] !== '\\') start -= 1;
100	
101	  const base = raw.slice(start, end);
102	  return base === '' ? FALLBACK_PROG : base;
103	}
104	
105	/* ------------------------------------------------------------------- IO --- */
106	
107	/** Synchronous sleep used only to back off from a full non-blocking pipe. */
108	function sleepMs(ms) {
109	  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
110	}
111	
112	/**
113	 * Write every byte of `bytes` to `fd`, synchronously.
114	 *
115	 * fs.writeSync is used instead of process.stdout.write because the stream is asynchronous
116	 * whenever fd 1/2 is a pipe: buffered bytes would then be at the mercy of process.exit().
117	 * Writing synchronously means output is already on the fd before exit() is reached, which
118	 * is what makes `node test3.mjs --a 5 --b x | cat` and the two-line error path reliable.
119	 */
120	function writeAll(fd, bytes) {
121	  let offset = 0;
122	  while (offset < bytes.length) {
123	    try {
124	      offset += writeSync(fd, bytes, offset, bytes.length - offset);
125	    } catch (err) {
126	      const code = err && err.code;
127	      if (code === 'EAGAIN') {
128	        // fd was inherited in non-blocking mode and its pipe buffer is full: wait for the
129	        // reader to drain, then continue where we left off.
130	        sleepMs(1);
131	      } else if (code === 'EINTR') {
132	        // Interrupted syscall: retry, like CPython's write-with-EINTR-retry loop.
133	        continue;
134	      } else if (code === 'EPIPE' || code === 'EBADF') {
135	        // Reader gone / fd closed. CPython reports BrokenPipeError at shutdown; we
136	        // deliberately ignore it so a truncated pipe cannot inject extra stderr noise or
137	        // change the exit status of an otherwise successful run.
138	        return;
139	      } else {
140	        throw err;
141	      }
142	    }
143	  }
144	}
145	
146	/** sys.stdout.write(s) -- byte-exact (surrogateescape encoded). */
147	export function writeStdout(s) {
148	  if (s === '') return;
149	  writeAll(1, encodeSurrogateescape(s));
150	}
151	
152	/** sys.stderr.write(s) -- byte-exact (surrogateescape encoded). */
153	export function writeStderr(s) {
154	  if (s === '') return;
155	  writeAll(2, encodeSurrogateescape(s));
156	}
157	
158	/**
159	 * SystemExit: terminate with `code`.
160	 *
161	 * Nothing needs flushing first -- every byte we emit went out through fs.writeSync above,
162	 * so there is no pending stream buffer for process.exit() to truncate. process.exitCode is
163	 * set first so the status is still correct in the (embedder-restricted) case where
164	 * process.exit() does not terminate the process.
165	 */
166	export function exit(code = 0) {
167	  process.exitCode = code;
168	  process.exit(code);
169	}
170	
171	/* -------------------------------------------------------- terminal size --- */
172	
173	// Upper bound applied to a COLUMNS value so downstream padding maths stays finite.
174	// Python happily carries an arbitrarily large int here; any value this big already means
175	// "never wrap", so clamping is unobservable.
176	const MAX_COLUMNS = 0x7fffffff;
177	
178	/**
179	 * shutil.get_terminal_size().columns, as argparse consumes it:
180	 *   1. int(os.environ['COLUMNS']) -- full CPython int() semantics (whitespace, sign,
181	 *      PEP 515 underscores, Unicode Nd digits); KeyError/ValueError -> 0.
182	 *   2. if that is <= 0, query the terminal attached to *stdout* (argparse asks about
183	 *      sys.__stdout__ even when it is about to write to stderr).
184	 *   3. otherwise fall back to 80.
185	 */
186	export function getTerminalColumns() {
187	  let columns = 0;
188	  const env = process.env.COLUMNS;
189	  if (typeof env === 'string') {
190	    try {
191	      const parsed = pyIntFromString(env);
192	      columns = parsed > BigInt(MAX_COLUMNS) ? MAX_COLUMNS : Number(parsed);
193	    } catch {
194	      columns = 0; // int() raised ValueError
195	    }
196	  }
197	
198	  if (columns <= 0) {
199	    const tty = process.stdout && process.stdout.columns;
200	    columns = typeof tty === 'number' && tty > 0 ? tty : 80;
201	  }
202	
203	  return columns;
204	}
