1	// Python `repr()` for str, and Python `str()` coercion.
2	//
3	// Mirrors CPython `Objects/unicodeobject.c:unicode_repr()` and the `str()`
4	// builtin. Iteration is by CODE POINT (not UTF-16 unit) so astral characters
5	// stay literal and unpaired surrogates (produced by argv surrogateescape
6	// decoding) render as `\udcff`-style escapes.
7	
8	import { PyTypeError } from './errors.mjs';
9	import { isPrintableCodePoint, toCodePoints } from './unicode.mjs';
10	
11	/**
12	 * Format one non-printable code point the way CPython's repr does:
13	 * `\xHH` for <= 0xFF, `\uHHHH` for <= 0xFFFF, `\UHHHHHHHH` otherwise.
14	 * Hex digits are LOWERCASE (verified against the reference, which prints
15	 * `'\x1f5'` for U+001F, `'​'` for U+200B and `'\U000e0001'` for U+E0001).
16	 */
17	function escapeCodePoint(cp) {
18	  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
19	  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
20	  return '\\U' + cp.toString(16).padStart(8, '0');
21	}
22	
23	/**
24	 * Python `repr(s)` for a str.
25	 *
26	 * CPython chooses the quote character first: `'` normally, but `"` when the
27	 * string contains a `'` and no `"` (so the apostrophe needs no escaping).
28	 * Then, per code point: the active quote and backslash are backslash-escaped,
29	 * tab/newline/carriage-return get their short escapes, anything that
30	 * `str.isprintable()` rejects becomes a numeric escape, and everything else is
31	 * emitted literally.
32	 */
33	export function reprStr(s) {
34	  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
35	  const out = [quote];
36	  for (const cp of toCodePoints(s)) {
37	    // Backslash and the active quote: `\\` and e.g. `\'`.
38	    if (cp === 0x5c /* \ */) {
39	      out.push('\\\\');
40	    } else if (String.fromCodePoint(cp) === quote) {
41	      out.push('\\' + quote);
42	    } else if (cp === 0x09) {
43	      out.push('\\t');
44	    } else if (cp === 0x0a) {
45	      out.push('\\n');
46	    } else if (cp === 0x0d) {
47	      out.push('\\r');
48	    } else if (!isPrintableCodePoint(cp)) {
49	      // Covers ASCII controls and DEL (Cc), Cf/Cs/Co/Cn, Zl/Zp and the
50	      // non-U+0020 Zs characters -- exactly Python's isprintable() complement.
51	      out.push(escapeCodePoint(cp));
52	    } else {
53	      out.push(String.fromCodePoint(cp));
54	    }
55	  }
56	  out.push(quote);
57	  return out.join('');
58	}
59	
60	/**
61	 * Python `str(value)` for the value kinds this program produces.
62	 *
63	 * Python ints are arbitrary precision, so they are modelled as BigInt; `str()`
64	 * of one is its plain decimal expansion (never a `5n` literal, never an
65	 * exponent). A JS number standing in for an int is widened through BigInt so
66	 * that e.g. 1e21 prints as `1000000000000000000000` rather than `1e+21`.
67	 */
68	export function pyStr(value) {
69	  if (typeof value === 'bigint') return value.toString();
70	  if (typeof value === 'string') return value;
71	  if (typeof value === 'number' && Number.isInteger(value)) {
72	    return BigInt(value).toString();
73	  }
74	  throw new PyTypeError(
75	    `pyStr() argument must be str or int, not ${typeof value}`
76	  );
77	}
